constexpr int factorial(int n) {
  if (n == 0) return 1;
  return n * factorial(n - 1);
}

int main() {
  constexpr int fact_5 = factorial(5); // Compile-time evaluation
  int x = 10;
  int fact_x = factorial(x); // Runtime evaluation (x is not a compile-time constant)
  constexpr int arr[factorial(3)] = {0}; // Array size determined at compile-time
  return 0;
}
